create table if not exists public.ticket_sla_policies (id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id) on delete cascade,name text not null,department_id uuid references public.departments(id) on delete set null,category_id uuid references public.ticket_categories(id) on delete set null,priority ticket_priority,first_response_minutes integer not null default 240,resolution_minutes integer not null default 1440,is_active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),constraint ticket_sla_minutes_check check(first_response_minutes>0 and resolution_minutes>0));
create index if not exists idx_ticket_sla_policies_lookup on public.ticket_sla_policies(company_id,department_id,category_id,priority) where is_active=true;
alter table public.tickets add column if not exists first_response_due_at timestamptz,add column if not exists first_responded_at timestamptz,add column if not exists sla_policy_id uuid,add column if not exists sla_breached_at timestamptz,add column if not exists waiting_reason text,add column if not exists escalation_level integer not null default 1;
alter table public.tickets add constraint tickets_sla_policy_fk foreign key(sla_policy_id) references public.ticket_sla_policies(id) on delete set null;
alter table public.tickets add constraint tickets_escalation_level_check check(escalation_level>=1);
create index if not exists idx_tickets_sla_response on public.tickets(company_id,first_response_due_at) where first_responded_at is null and archived_at is null;
create index if not exists idx_tickets_sla_resolution on public.tickets(company_id,due_at) where status not in('resolved','closed') and archived_at is null;
create or replace function private.apply_ticket_sla() returns trigger language plpgsql security definer set search_path=public,pg_catalog as $$ declare p public.ticket_sla_policies%rowtype; begin if new.sla_policy_id is null then select * into p from public.ticket_sla_policies where company_id=new.company_id and is_active=true and(department_id is null or department_id=new.department_id)and(category_id is null or category_id=new.category_id)and(priority is null or priority=new.priority)order by(department_id is not null)::int desc,(category_id is not null)::int desc,(priority is not null)::int desc limit 1; if found then new.sla_policy_id:=p.id;new.first_response_due_at:=coalesce(new.first_response_due_at,new.created_at+make_interval(mins=>p.first_response_minutes));new.due_at:=coalesce(new.due_at,new.created_at+make_interval(mins=>p.resolution_minutes));end if;end if;return new;end;$$;
drop trigger if exists tickets_apply_sla on public.tickets;
create trigger tickets_apply_sla before insert or update of department_id,category_id,priority on public.tickets for each row execute function private.apply_ticket_sla();
alter table public.ticket_sla_policies enable row level security;
create policy ticket_sla_select_member on public.ticket_sla_policies for select to authenticated using(company_id=any(current_company_id_array()));
create policy ticket_sla_manage_admin on public.ticket_sla_policies for all to authenticated using(private.has_company_role(company_id,array['admin'::membership_role,'hr'::membership_role,'manager'::membership_role])) with check(private.has_company_role(company_id,array['admin'::membership_role,'hr'::membership_role,'manager'::membership_role]));
